const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
function mean(a,w,h,r){const s=w+1,I=new Float64Array(s*(h+1)),out=new Float32Array(a.length);for(let y=0;y<h;y++){let row=0;for(let x=0;x<w;x++){row+=a[y*w+x];I[(y+1)*s+x+1]=I[y*s+x+1]+row;}}for(let y=0;y<h;y++)for(let x=0;x<w;x++){const l=Math.max(0,x-r),t=Math.max(0,y-r),rr=Math.min(w,x+r+1),b=Math.min(h,y+r+1);out[y*w+x]=(I[b*s+rr]-I[t*s+rr]-I[b*s+l]+I[t*s+l])/((rr-l)*(b-t));}return out;}
