function subject(a,w,h){let dark=0,bright=0,n=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(x<2||y<2||x>=w-2||y>=h-2){const v=a[y*w+x];dark+=+(v<.055);bright+=+(v>.91);n++;}const mode=bright/n>.72?'light':dark/n>.72?'dark':null;if(!mode)return{mask:null,mode:'unresolved'};const bg=Uint8Array.from(a,v=>+(mode==='light'?v>.86:v<.06)),mask=new Uint8Array(a.length);mask.fill(1);for(const c of components(bg,w,h,1))if(c.border)for(const k of c.pixels)mask[k]=0;const fraction=mask.reduce((a,b)=>a+b,0)/mask.length;return fraction>.01&&fraction<.94?{mask,mode}:{mask:null,mode:'unresolved'};}
