export function projectedDetailMM(x,y,w,h,p){const width=p.wallWidth??700,B=(p.bodySide??160)/2,wx=(x+.5-w/2)*width/w+(p.imageX??0),wy=(h/2-y-.5)*width/w+(p.imageY??80),M=Math.max(1,Math.max(Math.abs(wx),Math.abs(wy))/B),blur=(p.emitter??1.2)*(M-1),print=(p.minWeb??.8)*Math.max(M,M*M*B/(p.sourceZ??140));return Math.max(p.detailMM??0,blur*1.15,print);}
export function prepareShadowTarget(gray,iw,ih,p={}){const mode=p.stencilMode??'legacy',base=prepareTarget(gray,iw,ih,p);if(mode==='legacy')return base;if(mode==='artwork'){const raw=base.raw.slice();let filled=0;for(const c of components(raw,base.nx,base.ny,0)){if(c.border)continue;const diameter=projectedDetailMM(c.cx,c.cy,base.nx,base.ny,p)*base.nx/(p.wallWidth??700);if(c.area<Math.max(4,Math.PI*(diameter*.5)**2)){for(const k of c.pixels)raw[k]=1;filled+=c.area;}}const ink=raw.reduce((a,b)=>a+b,0);return{...base,originalRaw:base.raw.slice(),raw,target:raw.slice(),stats:{...base.stats,stencilMode:mode,styleDirection:'minimal-silhouette-1',preparation:'monochrome artwork; projection-aware removal of micro apertures',semanticRecognition:false,filledLightPixels:filled,changedFromThreshold:filled/raw.length,inkCoverage:ink/raw.length,blackPixels:ink,components:components(raw,base.nx,base.ny,1).length,holes:components(raw,base.nx,base.ny,0).filter(c=>!c.border).length,needsSubjectReview:true}};}if(!['minimal','bold','balanced','detail'].includes(mode))throw Error('Unknown photographic stencil mode.');const {nx:w,ny:h}=base,strength={minimal:2.1,bold:1.5,balanced:1,detail:.6}[mode],r=Math.max(1,Math.round(w/110*strength)),tone=guided(base.tones,w,h,r,.012*strength),fg=subject(tone,w,h),local=mean(tone,w,h,Math.max(5,Math.round(w*.045))),mid=quantile(tone,fg.mask,mode==='minimal'?.62:mode==='bold'?.59:mode==='balanced'?.51:.44),raw=new Uint8Array(tone.length),bias=(p.threshold??.34)-.34;
const distance=new Float32Array(tone.length);distance.fill(1e5);if(fg.mask){for(let y=0;y<h;y++)for(let x=0;x<w;x++){const k=y*w+x;if(!fg.mask[k])distance[k]=0;else distance[k]=Math.min(distance[k],x?distance[k-1]+1:0,y?distance[k-w]+1:0);}for(let y=h-1;y>=0;y--)for(let x=w-1;x>=0;x--){const k=y*w+x;distance[k]=Math.min(distance[k],x<w-1?distance[k+1]+1:0,y<h-1?distance[k+w]+1:0);}}
// A black perimeter protects the external silhouette. Interior tones form apertures.
for(let y=0;y<h;y++)for(let x=0;x<w;x++){const k=y*w+x,inSubject=!fg.mask||fg.mask[k],rim=fg.mask&&fg.mask[k]&&distance[k]<=Math.max(2,projectedDetailMM(x,y,w,h,p)*w/(p.wallWidth??700)*1.25),cut=clamp(.34+.45*(local[k]-mid)+bias+(mode==='minimal'?.075:mode==='bold'?.055:mode==='balanced'?.015:-.02),.08,.85);raw[k]=+(inSubject&&(rim||tone[k]<=cut));}
let removedDark=0,filledLight=0;for(const value of[1,0])for(const c of components(raw,w,h,value)){if(!value&&c.border)continue;const mm=projectedDetailMM(c.cx,c.cy,w,h,p),diameter=Math.max(1,mm*w/(p.wallWidth??700)),minimum=Math.max(3,Math.PI*(diameter*.45)**2*strength);if(c.area<minimum){for(const k of c.pixels)raw[k]=1-value;if(value)removedDark+=c.area;else filledLight+=c.area;}}
// Majority filtering suppresses short sawteeth; it does not blur the rendered shadow.
const filtered=mean(raw,w,h,1),next=raw.slice();for(let k=0;k<raw.length;k++){if(filtered[k]>.77)next[k]=1;else if(filtered[k]<.23)next[k]=0;}raw.set(next);
if(mode==='minimal'){for(const c of components(raw,w,h,0))if(!c.border&&c.area<Math.max(12,w*h*.0008)){for(const k of c.pixels)raw[k]=1;filledLight+=c.area;}for(const c of components(raw,w,h,1))if(c.area<Math.max(8,w*h*.00035)){for(const k of c.pixels)raw[k]=0;removedDark+=c.area;}}
let changes=0,ink=0;for(let k=0;k<raw.length;k++){changes+=+(raw[k]!==base.raw[k]);ink+=raw[k];}const holes=components(raw,w,h,0).filter(c=>!c.border).length,parts=components(raw,w,h,1).length;
return{...base,originalRaw:base.raw,raw,target:raw.slice(),stats:{...base.stats,preparation:'guided-filter + adaptive tone + projection-aware component cleanup',stencilMode:mode,styleDirection:mode==='minimal'?'minimal-silhouette-1':'comparison',background:fg.mode,semanticRecognition:false,removedDarkPixels:removedDark,filledLightPixels:filledLight,changedFromThreshold:changes/raw.length,changedRatio:changes/raw.length,inkCoverage:ink/raw.length,components:parts,blackPixels:ink,holes,minimumDetailsVaryWithProjection:true,needsSubjectReview:true}};}
